import sys

def solve():
    # Read all input from standard input
    input_data = sys.stdin.read().split()

    if not input_data:
        return

    iterator = iter(input_data)

    try:
        H = int(next(iterator))
        W = int(next(iterator))
    except StopIteration:
        return

    grid = []
    for _ in range(H):
        try:
            grid.append(next(iterator))
        except StopIteration:
            break

    # Initialize bounding box coordinates
    # min_r, min_c should be large, max_r, max_c should be small
    min_r, max_r = H, -1
    min_c, max_c = W, -1

    # Find the bounding box of all '#' cells
    # We iterate through the grid to find the min and max row/col indices for '#'
    for r in range(H):
        row_str = grid[r]
        for c in range(W):
            if row_str[c] == '#':
                if r < min_r:
                    min_r = r
                if r > max_r:
                    max_r = r
                if c < min_c:
                    min_c = c
                if c > max_c:
                    max_c = c

    # According to constraints, there is at least one '#', so min_r <= max_r and min_c <= max_c.
    # If the minimal bounding box contains any '.', then it's impossible to form a valid rectangle
    # because any valid rectangle must cover all '#' and thus cover the minimal bounding box.

    possible = True
    for r in range(min_r, max_r + 1):
        row_str = grid[r]
        for c in range(min_c, max_c + 1):
            if row_str[c] == '.':
                possible = False
                break
        if not possible:
            break

    if possible:
        print("Yes")
    else:
        print("No")

if __name__ == '__main__':
    solve()
