sys.setrecursionlimit(2000)

def solve():
    # Read all input from stdin
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    iterator = iter(input_data)

    try:
        N = int(next(iterator))
        p = int(next(iterator))
    except StopIteration:
        return

    A = []
    for i in range(N):
        row = []
        for j in range(N):
            row.append(int(next(iterator)))
        A.append(row)

    # Identify zeros
    zeros = []
    for i in range(N):
        for j in range(N):
            if A[i][j] == 0:
                zeros.append((i, j))
    K = len(zeros)

    # Helper function for matrix multiplication
    def mat_mul(X, Y, mod):
        # Transpose Y for better cache locality
        Y_T = list(zip(*Y))
        Z = []
        for i in range(N):
            row_X = X[i]
            row_Z = []
            for j in range(N):
                # Compute dot product of row i of X and col j of Y (which is row j of Y_T)
                # Using sum and generator expression
                s = 0
                for k in range(N):
                    s += row_X[k] * Y_T[j][k]
                row_Z.append(s % mod)
            Z.append(row_Z)
        return Z

    # Helper function for matrix power
    def mat_pow(X, exp, mod):
        # Identity matrix
        res = [[1 if i == j else 0 for j in range(N)] for i in range(N)]
        base = X
        while exp > 0:
            if exp % 2 == 1:
                res = mat_mul(res, base, mod)
            base = mat_mul(base, base, mod)
            exp //= 2
        return res

    if p == 2:
        # Special case for p=2
        # Replace all zeros with 1
        B = []
        for i in range(N):
            row = []
            for j in range(N):
                if A[i][j] == 0:
                    row.append(1)
                else:
                    row.append(A[i][j])
            B.append(row)

        # Compute B^2 mod 2
        # Since entries are 0 or 1, we can just compute sum mod 2
        # But mat_mul handles mod 2 correctly
        res = mat_pow(B, 2, 2)

        for row in res:
            print(*(row))

    else:
        # General case p > 2
        # Compute S = A^p mod p
        S = mat_pow(A, p, p)

        # Add corrections
        for r, c in zeros:
            if r == c:
                # Diagonal zero
                # Add A_{i,r} to S_{i,r} for i != r
                # Add A_{r,j} to S_{r,j} for j != r
                # S_{r,r} is unchanged (contribution is 0 mod p)

                # We can iterate and update
                # To avoid O(N) inside loop which is O(N^3) total, it's fine since N=100
                # But we can optimize slightly

                # Update column r
                for i in range(N):
                    if i != r:
                        S[i][r] = (S[i][r] + A[i][r]) % p

                # Update row r
                for j in range(N):
                    if j != r:
                        S[r][j] = (S[r][j] + A[r][j]) % p

            else:
                # Off-diagonal zero
                if p == 3:
                    # Add A_{c,r} to S_{r,c}
                    S[r][c] = (S[r][c] + A[c][r]) % p
                else:
                    # p > 3, no contribution
                    pass

        # Multiply by (-1)^K mod p
        if K % 2 == 1:
            factor = p - 1
        else:
            factor = 1

        for i in range(N):
            for j in range(N):
                S[i][j] = (S[i][j] * factor) % p

        for row in S:
            print(*(row))

if __name__ == '__main__':
    solve()
