from typing import List

class Solution:
    def sortMatrix(self, grid: List[List[int]]) -> List[List[int]]:
        n = len(grid)
        diagonals = {}

        # Collect elements for each diagonal
        # A diagonal is uniquely identified by the difference k = row - col
        for r in range(n):
            for c in range(n):
                k = r - c
                if k not in diagonals:
                    diagonals[k] = []
                diagonals[k].append(grid[r][c])

        # Sort elements based on the problem rules
        for k in diagonals:
            if k >= 0:
                # Bottom-left triangle (including middle diagonal): non-increasing (descending)
                diagonals[k].sort(reverse=True)
            else:
                # Top-right triangle: non-decreasing (ascending)
                diagonals[k].sort()

        # Reconstruct the matrix
        # We need to track the current index for each diagonal to place elements back
        # Since we iterate r from 0 to n-1, for a fixed k, r increases.
        # The sorted list corresponds to the order of r (top to bottom).
        current_indices = {k: 0 for k in diagonals}

        for r in range(n):
            for c in range(n):
                k = r - c
                grid[r][c] = diagonals[k][current_indices[k]]
                current_indices[k] += 1

        return grid

if __name__ == "__main__":
    # Read all input from stdin
    input_data = sys.stdin.read().strip()
    if input_data:
        # Parse the input string into a list of lists
        grid = eval(input_data)
        solution = Solution()
        result = solution.sortMatrix(grid)
        print(result)
