    def hasSpecialSubstring(self, s: str, k: int) -> bool:
        n = len(s)
        # Iterate through all possible starting positions for a substring of length k
        for i in range(n - k + 1):
            # Check if substring s[i:i+k] consists of only one distinct character
            char = s[i]
            is_uniform = True
            for j in range(i + 1, i + k):
                if s[j] != char:
                    is_uniform = False
                    break

            if not is_uniform:
                continue

            # Check left boundary condition
            # If there is a character immediately before the substring, it must be different
            if i > 0:
                if s[i-1] == char:
                    continue

            # Check right boundary condition
            # If there is a character immediately after the substring, it must be different
            if i + k < n:
                if s[i+k] == char:
                    continue

            # If all conditions are met, return True
