class Solution:
    def numberOfComponents(self, properties: List[List[int]], k: int) -> int:
        n = len(properties)
        if n == 0:
            return 0

        # DSU initialization
        parent = list(range(n))

        def find(i):
            if parent[i] != i:
                parent[i] = find(parent[i])
            return parent[i]

        def union(i, j):
            root_i = find(i)
            root_j = find(j)
            if root_i != root_j:
                parent[root_i] = root_j
                return True
            return False

        # Precompute sets for each property row to speed up intersection
        sets = [set(row) for row in properties]

        # Iterate over all pairs to build the graph (implicitly via DSU)
        for i in range(n):
            for j in range(i + 1, n):
                # Optimization: if either set is smaller than k, intersection cannot be >= k
                if len(sets[i]) < k or len(sets[j]) < k:
                    continue

                # Check intersection size
                # Using set intersection is efficient enough for m <= 100
                if len(sets[i] & sets[j]) >= k:
                    union(i, j)

        # Count connected components
        components = 0
        for i in range(n):
            if parent[i] == i:
                components += 1
        return components

if __name__ == "__main__":
