def solve():
    # Read all input at once
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    iterator = iter(input_data)

    try:
        N = int(next(iterator))
        X = int(next(iterator))

        A = [0] * (N + 1)
        for i in range(1, N + 1):
            A[i] = int(next(iterator))

        B = [0] * (N + 1)
        for i in range(1, N + 1):
            B[i] = int(next(iterator))

        P = [0] * (N + 1)
        for i in range(1, N + 1):
            P[i] = int(next(iterator))

        Q = [0] * (N + 1)
        for i in range(1, N + 1):
            Q[i] = int(next(iterator))
    except StopIteration:
        return

    # Identify S_R and S_B
    S_R = [i for i in range(1, N + 1) if A[i] == 1]
    S_B = [i for i in range(1, N + 1) if B[i] == 1]

    # Function to get cycle info
    def get_cycle_info(start_node, perm):
        cycle = []
        curr = start_node
        while True:
            cycle.append(curr)
            curr = perm[curr]
            if curr == start_node:
                break
        return cycle

    # Get cycle for X in G_R
    cycle_R = get_cycle_info(X, P)
    # Map node to index in cycle
    pos_R = [-1] * (N + 1)
    for i, node in enumerate(cycle_R):
        pos_R[node] = i

    # Check S_R
    for u in S_R:
        if pos_R[u] == -1:
            print(-1)
            return

    # Construct U_R
    if not S_R:
        U_R = set()
    else:
        max_dist = 0
        for u in S_R:
            d = (len(cycle_R) - pos_R[u]) % len(cycle_R)
            if d > max_dist:
                max_dist = d

        start_idx = len(cycle_R) - max_dist
        U_R = set(cycle_R[start_idx:])

    # Get cycle for X in G_B
    cycle_B = get_cycle_info(X, Q)
    pos_B = [-1] * (N + 1)
    for i, node in enumerate(cycle_B):
        pos_B[node] = i

    # Check S_B
    for v in S_B:
        if pos_B[v] == -1:
            print(-1)
            return

    # Construct U_B
    if not S_B:
        U_B = set()
    else:
        max_dist = 0
        for v in S_B:
            d = (len(cycle_B) - pos_B[v]) % len(cycle_B)
            if d > max_dist:
                max_dist = d

        start_idx = len(cycle_B) - max_dist
        U_B = set(cycle_B[start_idx:])

    # Union
    U = U_R | U_B
    in_U = [False] * (N + 1)
    for u in U:
        in_U[u] = True

    # Build dependency graph
    adj = [[] for _ in range(N + 1)]

    for u in U_R:
        v = P[u]
        if in_U[v]:
            adj[u].append(v)

    for u in U_B:
        v = Q[u]
        if in_U[v]:
            adj[u].append(v)

    # Check for cycles using iterative DFS
    state = [0] * (N + 1) # 0: unvisited, 1: visiting, 2: visited
    adj_idx = [0] * (N + 1)

    stack = []
    for u in U:
        if state[u] == 0:
            stack.append(u)
            while stack:
                curr = stack[-1]
                if state[curr] == 0:
                    state[curr] = 1

                idx = adj_idx[curr]
                neighbors = adj[curr]

                if idx < len(neighbors):
                    neighbor = neighbors[idx]
                    adj_idx[curr] += 1

                    if state[neighbor] == 1:
                        print(-1)
                        return
                    if state[neighbor] == 0:
                        stack.append(neighbor)
                else:
                    state[curr] = 2
                    stack.pop()

    print(len(U))

